<?php
// ============================================================
// Admin Inventory History Oversight - admin_inventory_history.php
// Rebuilt to support Merchandise & Fuel movement tabs, summary cards,
// advanced filters, details modals, and printing/exporting.
// ============================================================
if (session_status() === PHP_SESSION_NONE) session_start();
$page_id = 'admin_inventory_history';
require_once __DIR__ . '/../backend/lib.php';
require_once __DIR__ . '/db_connect.php';
require_login();  $me  = current_user();
$role  = role_key($me['role'] ?? '');
$station_id = (int)user_station_id();  // ── Module gate ───────────────────────────────────────────────
if (!in_array($role, ['superadmin', 'developer']) && !is_module_enabled('inventory')) {  render_module_disabled_page('Inventory');
}
if (!in_array($role, ['admin','superadmin'])) {  header('Location: dashboard.php');  exit;  }
if ($station_id <= 0 && $role === 'admin') {  render_no_station_page('admin_dashboard.php');  }  // ── User filters input ────────────────────────────────────────
$start_date = $_GET['start'] ?? date('Y-m-d', strtotime('-30 days'));
$end_date  = $_GET['end']  ?? date('Y-m-d');
$active_tab = $_GET['tab']  ?? 'merch';
if (!in_array($active_tab, ['merch', 'fuel'])) {  $active_tab = 'merch';
}  $search  = trim($_GET['search'] ?? '');
$category  = trim($_GET['category'] ?? '');
$fuel_type  = trim($_GET['fuel_type'] ?? '');
$move_type  = trim($_GET['move_type'] ?? '');
$perf_by  = trim($_GET['perf_by'] ?? '');  // ── AJAX Endpoint: Product Details ───────────────────────────
if (isset($_GET['action']) && $_GET['action'] === 'get_product_details') {  $prod_id = (int)($_GET['product_id'] ?? 0);  header('Content-Type: application/json');  try {  // Fetch product info  $stmt = $pdo->prepare("  SELECT ip.id, ip.sku, ip.product_name, ip.category, COALESCE(si.unit, 'pcs') AS unit, ip.supplier,  COALESCE(si.stock_level, ip.stock, 0) AS current_stock,  COALESCE(si.reorder_level, ip.min_stock, 10) AS reorder_level,  COALESCE(si.capacity, ip.max_stock, 100) AS max_stock,  ip.unit_price, ip.unit_cost,  COALESCE(si.status, 'active') AS status  FROM inventory_products ip  LEFT JOIN station_inventory si ON si.product_id = ip.id AND si.station_id = ?  WHERE ip.id = ?  ");  $stmt->execute([$station_id, $prod_id]);  $prod = $stmt->fetch(PDO::FETCH_ASSOC);  if (!$prod) {  echo json_encode(['success' => false, 'message' => 'Product not found']);  exit;  }  // Fetch total deliveries  $stmt = $pdo->prepare("SELECT SUM(qty_received) FROM merchandise_stock_in WHERE product_id = ? AND station_id = ?");  $stmt->execute([$prod_id, $station_id]);  $total_deliveries = (float)$stmt->fetchColumn() ?: 0;  // Fetch total released/sold  $stmt = $pdo->prepare("  SELECT SUM(mti.quantity)  FROM merchandise_transaction_items mti  JOIN merchandise_transactions mt ON mti.transaction_id = mt.id  WHERE mti.product_id = ? AND mt.station_id = ? AND mt.validation_status IN ('Official','Completed','Approved','Adjusted')  ");  $stmt->execute([$prod_id, $station_id]);  $total_released = (float)$stmt->fetchColumn() ?: 0;  // Last delivery date  $stmt = $pdo->prepare("SELECT MAX(encoded_at) FROM merchandise_stock_in WHERE product_id = ? AND station_id = ?");  $stmt->execute([$prod_id, $station_id]);  $last_delivery_date = $stmt->fetchColumn() ?: '—';  if ($last_delivery_date !== '—') $last_delivery_date = date('M d, Y g:i A', strtotime($last_delivery_date));  // Last stock movement  $stmt = $pdo->prepare("  SELECT created_at, action, notes  FROM inventory_logs  WHERE product_id = ? AND station_id = ?  ORDER BY created_at DESC LIMIT 1  ");  $stmt->execute([$prod_id, $station_id]);  $last_log = $stmt->fetch(PDO::FETCH_ASSOC);  $last_movement = $last_log ? (date('M d, Y g:i A', strtotime($last_log['created_at'])) . ' (' . ucfirst($last_log['action']) . ')') : '—';  echo json_encode([  'success' => true,  'product' => $prod,  'total_deliveries' => $total_deliveries,  'total_released' => $total_released,  'last_delivery_date' => $last_delivery_date,  'last_movement' => $last_movement  ]);  exit;  } catch (Exception $e) {  echo json_encode(['success' => false, 'message' => $e->getMessage()]);  exit;  }
}  // ── SQL QUERIES BUILDER ──────────────────────────────────────  // 1. Merchandise SQL
$merch_where = " WHERE 1=1 ";
$merch_params = [$station_id, $station_id, $station_id];  if ($search !== '') {  $merch_where .= " AND (product_name LIKE ? OR sku LIKE ? OR reference_no LIKE ? OR movement_id LIKE ?)";  $s_term = "%$search%";  $merch_params[] = $s_term;  $merch_params[] = $s_term;  $merch_params[] = $s_term;  $merch_params[] = $s_term;
}
if ($start_date !== '' && $end_date !== '') {  $merch_where .= " AND DATE(date_time) BETWEEN ? AND ?";  $merch_params[] = $start_date;  $merch_params[] = $end_date;
}
if ($category !== '') {  $merch_where .= " AND category = ?";  $merch_params[] = $category;
}
if ($move_type !== '') {  if ($move_type === 'Release' || $move_type === 'Sale') {  $merch_where .= " AND (movement_type = 'Sale' OR movement_type = 'Release')";  } else {  $merch_where .= " AND movement_type = ?";  $merch_params[] = $move_type;  }
}
if ($perf_by !== '') {  $merch_where .= " AND performed_by_id = ?";  $merch_params[] = (int)$perf_by;
}  $merch_sql = "
SELECT * FROM (  SELECT  CONCAT('DEL-', msi.id) AS movement_id,  msi.encoded_at AS date_time,  msi.po_number AS reference_no,  msi.product_id,  msi.product_name,  msi.sku,  msi.category,  'Delivery' AS movement_type,  msi.qty_received AS quantity,  msi.stock_before AS prev_stock,  msi.stock_after AS new_stock,  msi.encoded_by AS performed_by_id,  COALESCE(NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '), u.username, 'System') AS performed_by,  msi.remarks,  'Completed' AS status  FROM merchandise_stock_in msi  LEFT JOIN users u ON msi.encoded_by = u.id  WHERE msi.station_id = ?  UNION ALL  SELECT  CONCAT('SALE-', mt.transaction_id, '-', mti.id) AS movement_id,  mt.transaction_date AS date_time,  mt.transaction_id AS reference_no,  mti.product_id,  mti.product_name,  ip.sku,  mti.category,  'Sale' AS movement_type,  -mti.quantity AS quantity,  0 AS prev_stock,  0 AS new_stock,  mt.staff_id AS performed_by_id,  COALESCE(NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '), u.username, 'System') AS performed_by,  COALESCE(mt.remarks, mt.staff_remarks) AS remarks,  mt.validation_status AS status  FROM merchandise_transaction_items mti  JOIN merchandise_transactions mt ON mti.transaction_id = mt.id  LEFT JOIN inventory_products ip ON mti.product_id = ip.id  LEFT JOIN users u ON mt.staff_id = u.id  WHERE mt.station_id = ? AND mt.validation_status IN ('Official','Completed','Approved','Adjusted') AND mti.item_type = 'merchandise'  UNION ALL  SELECT  CONCAT('ADJ-', il.id) AS movement_id,  il.created_at AS date_time,  '—' AS reference_no,  il.product_id,  ip.product_name,  ip.sku,  ip.category,  CASE  WHEN il.notes LIKE '%damaged%' THEN 'Damaged Item'  WHEN il.notes LIKE '%variance%' OR il.notes LIKE '%correction%' OR il.notes LIKE '%count%' THEN 'Stock Correction'  ELSE 'Adjustment'  END AS movement_type,  il.quantity_change AS quantity,  COALESCE(il.quantity_before, 0) AS prev_stock,  COALESCE(il.quantity_after, 0) AS new_stock,  il.user_id AS performed_by_id,  COALESCE(NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '), u.username, 'System') AS performed_by,  il.notes AS remarks,  'Approved' AS status  FROM inventory_logs il  JOIN inventory_products ip ON il.product_id = ip.id  LEFT JOIN users u ON il.user_id = u.id  WHERE il.station_id = ? AND il.action = 'adjustment'
) AS merch_moves
$merch_where
ORDER BY date_time DESC
";  // 2. Fuel SQL
$fuel_where = " WHERE 1=1 ";
$fuel_params = [$station_id, $station_id, $station_id];  if ($search !== '') {  $fuel_where .= " AND (tank LIKE ? OR reference_no LIKE ? OR movement_id LIKE ?)";  $s_term = "%$search%";  $fuel_params[] = $s_term;  $fuel_params[] = $s_term;  $fuel_params[] = $s_term;
}
if ($start_date !== '' && $end_date !== '') {  $fuel_where .= " AND DATE(date_time) BETWEEN ? AND ?";  $fuel_params[] = $start_date;  $fuel_params[] = $end_date;
}
if ($fuel_type !== '') {  $fuel_where .= " AND fuel_type = ?";  $fuel_params[] = $fuel_type;
}
if ($move_type !== '') {  $fuel_where .= " AND movement_type = ?";  $fuel_params[] = $move_type;
}
if ($perf_by !== '') {  $fuel_where .= " AND performed_by_id = ?";  $fuel_params[] = (int)$perf_by;
}  $fuel_sql = "
SELECT * FROM (  SELECT  CONCAT('DEL-', fd.id) AS movement_id,  fd.created_at AS date_time,  fd.invoice_no AS reference_no,  fd.tank_assigned AS tank,  fd.fuel_type,  'Delivery' AS movement_type,  fd.delivery_liters AS liters,  0 AS prev_volume,  0 AS new_volume,  fd.received_by AS performed_by_id,  COALESCE(NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '), u.username, 'System') AS performed_by,  fd.notes AS remarks,  fd.status  FROM fuel_deliveries fd  LEFT JOIN users u ON fd.received_by = u.id  WHERE fd.station_id = ? AND fd.status IN ('Verified','Approved')  UNION ALL  SELECT  ft.transaction_id AS movement_id,  ft.transaction_date AS date_time,  ft.transaction_id AS reference_no,  CONCAT('Pump #', IFNULL(ft.pump_id,'—')) AS tank,  ft.fuel_type,  'Dispensed' AS movement_type,  -ft.liters_sold AS liters,  0 AS prev_volume,  0 AS new_volume,  ft.staff_id AS performed_by_id,  COALESCE(NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '), u.username, 'System') AS performed_by,  ft.notes AS remarks,  ft.status  FROM fuel_transactions ft  LEFT JOIN users u ON ft.staff_id = u.id  WHERE ft.station_id = ? AND ft.status IN ('Approved','approved','Completed')  UNION ALL  SELECT  CONCAT('ADJ-', fa.id) AS movement_id,  fa.created_at AS date_time,  '—' AS reference_no,  '—' AS tank,  fa.fuel_type,  CASE  WHEN fa.adjustment_type = 'variance' OR fa.reason LIKE '%variance%' OR fa.notes LIKE '%variance%' THEN 'Fuel Variance'  WHEN fa.adjustment_type = 'correction' OR fa.reason LIKE '%correction%' OR fa.notes LIKE '%correction%' OR fa.notes LIKE '%count%' THEN 'Stock Correction'  ELSE 'Adjustment'  END AS movement_type,  fa.liters AS liters,  COALESCE(fa.previous_value, 0) AS prev_volume,  COALESCE(fa.new_value, 0) AS new_volume,  fa.user_id AS performed_by_id,  COALESCE(NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '), u.username, 'System') AS performed_by,  fa.reason AS remarks,  fa.status  FROM fuel_adjustments fa  LEFT JOIN users u ON fa.user_id = u.id  WHERE fa.station_id = ? AND fa.status = 'Approved'
) AS fuel_moves
$fuel_where
ORDER BY date_time DESC
";  // ── PRINT & EXPORT LOGIC ─────────────────────────────────────
if (isset($_GET['print'])) {  if ($active_tab === 'merch') {  $stmt = $pdo->prepare($merch_sql);  $stmt->execute($merch_params);  } else {  $stmt = $pdo->prepare($fuel_sql);  $stmt->execute($fuel_params);  }  $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);  // Fetch station info  $station_name = 'Petron Carmen';  $station_address = 'Vamenta Blvd., Carmen, Cagayan de Oro';  try {  $st_stmt = $pdo->prepare("SELECT * FROM stations WHERE id = ? LIMIT 1");  $st_stmt->execute([$station_id]);  $station = $st_stmt->fetch(PDO::FETCH_ASSOC);  if ($station) {  if (!empty($station['name'])) $station_name = $station['name'];  if (!empty($station['address'])) $station_address = $station['address'];  }  } catch (Exception $e) {}  ?>  <!DOCTYPE html>  <html>  <head>  <title>Inventory History Report - <?= htmlspecialchars($station_name) ?></title>  <style>  body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding: 20px; font-size: 11px; color: #333; }  .header { text-align: center; margin-bottom: 25px; border-bottom: 2px solid #002F70; padding-bottom: 10px; }  .header h1 { margin: 0; color: #002F70; font-size: 18px; text-transform: uppercase; }  .header p { margin: 3px 0; color: #555; }  table { width: 100%; border-collapse: collapse; margin-top: 15px; }  th, td { border: 1px solid #cbd5e1; padding: 7px 9px; text-align: left; }  th { background-color: #002F70; color: white; font-weight: bold; text-transform: uppercase; font-size: 9px; }  tr:nth-child(even) { background-color: #f8fafc; }  .right { text-align: right; }  .badge { display: inline-block; padding: 2px 5px; border-radius: 3px; font-size: 9px; font-weight: bold; text-transform: uppercase; }  .badge-delivery { background: #dcfce7; color: #166534; }  .badge-sale { background: #fee2e2; color: #991b1b; }  .badge-dispensed { background: #fee2e2; color: #991b1b; }  .badge-adjustment { background: #fef9c3; color: #854d0e; }  .badge-damaged-item { background: #fee2e2; color: #dc2626; border: 1px solid #fca5a5; }  .badge-stock-correction { background: #eff6ff; color: #1e40af; border: 1px solid #bfdbfe; }  .badge-fuel-variance { background: #fef3c7; color: #d97706; border: 1px solid #fde68a; }  </style>  </head>  <body onload="window.print()">  <div class="header">  <h1><?= htmlspecialchars($station_name) ?></h1>  <p><?= htmlspecialchars($station_address) ?></p>  <h3>Inventory History - <?= $active_tab === 'merch' ? 'Merchandise Movements' : 'Fuel Movements' ?></h3>  <p>Period: <?= htmlspecialchars($start_date) ?> to <?= htmlspecialchars($end_date) ?></p>  </div>  <table>  <thead>  <?php if ($active_tab === 'merch'): ?>  <tr>  <th>Movement ID</th>  <th>Date & Time</th>  <th>Reference No.</th>  <th>Product Name</th>  <th>SKU</th>  <th>Movement Type</th>  <th class="right">Quantity</th>  <th class="right">Prev Stock</th>  <th class="right">New Stock</th>  <th>Performed By</th>  </tr>  <?php else: ?>  <tr>  <th>Movement ID</th>  <th>Date & Time</th>  <th>Reference No.</th>  <th>Tank</th>  <th>Fuel Type</th>  <th>Movement Type</th>  <th class="right">Liters</th>  <th class="right">Prev Volume</th>  <th class="right">New Volume</th>  <th>Performed By</th>  </tr>  <?php endif; ?>  </thead>  <tbody>  <?php if (empty($rows)): ?>  <tr><td colspan="10" style="text-align:center;">No movement records found.</td></tr>  <?php else: ?>  <?php foreach ($rows as $r): ?>  <?php if ($active_tab === 'merch'): ?>  <tr>  <td><code><?= htmlspecialchars($r['movement_id']) ?></code></td>  <td><?= date('M d, Y g:i A', strtotime($r['date_time'])) ?></td>  <td><?= htmlspecialchars($r['reference_no']) ?></td>  <td><strong><?= htmlspecialchars($r['product_name']) ?></strong></td>  <td><?= htmlspecialchars($r['sku'] ?: '—') ?></td>  <td><span class="badge badge-<?= str_replace(' ', '-', strtolower($r['movement_type'])) ?>"><?= htmlspecialchars($r['movement_type']) ?></span></td>  <td class="right"><?= number_format($r['quantity']) ?></td>  <td class="right"><?= number_format($r['prev_stock']) ?></td>  <td class="right"><?= number_format($r['new_stock']) ?></td>  <td><?= htmlspecialchars($r['performed_by']) ?></td>  </tr>  <?php else: ?>  <tr>  <td><code><?= htmlspecialchars($r['movement_id']) ?></code></td>  <td><?= date('M d, Y g:i A', strtotime($r['date_time'])) ?></td>  <td><?= htmlspecialchars($r['reference_no']) ?></td>  <td><?= htmlspecialchars($r['tank']) ?></td>  <td><strong><?= htmlspecialchars($r['fuel_type']) ?></strong></td>  <td><span class="badge badge-<?= str_replace(' ', '-', strtolower($r['movement_type'])) ?>"><?= htmlspecialchars($r['movement_type']) ?></span></td>  <td class="right"><?= number_format($r['liters'], 2) ?>L</td>  <td class="right"><?= number_format($r['prev_volume'], 2) ?>L</td>  <td class="right"><?= number_format($r['new_volume'], 2) ?>L</td>  <td><?= htmlspecialchars($r['performed_by']) ?></td>  </tr>  <?php endif; ?>  <?php endforeach; ?>  <?php endif; ?>  </tbody>  </table>  </body>  </html>  <?php  exit;
}  if (isset($_GET['export'])) {  $etype = $_GET['export'];  $filename = ($active_tab === 'merch' ? 'merchandise_movements_' : 'fuel_movements_') . date('Ymd');  if ($etype === 'csv' || $etype === 'excel') {  header('Content-Type: text/csv; charset=utf-8');  header('Content-Disposition: attachment; filename="' . $filename . '.csv"');  $out = fopen('php://output', 'w');  if ($active_tab === 'merch') {  $stmt = $pdo->prepare($merch_sql);  $stmt->execute($merch_params);  fputcsv($out, ['Movement ID', 'Date & Time', 'Reference No.', 'Product Name', 'SKU', 'Category', 'Movement Type', 'Quantity', 'Previous Stock', 'New Stock', 'Performed By', 'Status', 'Remarks']);  while ($r = $stmt->fetch(PDO::FETCH_ASSOC)) {  fputcsv($out, [$r['movement_id'], $r['date_time'], $r['reference_no'], $r['product_name'], $r['sku'], $r['category'], $r['movement_type'], $r['quantity'], $r['prev_stock'], $r['new_stock'], $r['performed_by'], $r['status'], $r['remarks']]);  }  } else {  $stmt = $pdo->prepare($fuel_sql);  $stmt->execute($fuel_params);  fputcsv($out, ['Movement ID', 'Date & Time', 'Reference No.', 'Tank', 'Fuel Type', 'Movement Type', 'Liters', 'Previous Volume', 'New Volume', 'Performed By', 'Status', 'Remarks']);  while ($r = $stmt->fetch(PDO::FETCH_ASSOC)) {  fputcsv($out, [$r['movement_id'], $r['date_time'], $r['reference_no'], $r['tank'], $r['fuel_type'], $r['movement_type'], $r['liters'], $r['prev_volume'], $r['new_volume'], $r['performed_by'], $r['status'], $r['remarks']]);  }  }  fclose($out);  exit;  }
}  // Execute queries for UI display
try {  $stmt = $pdo->prepare($merch_sql);  $stmt->execute($merch_params);  $merch_rows = $stmt->fetchAll(PDO::FETCH_ASSOC);  $stmt = $pdo->prepare($fuel_sql);  $stmt->execute($fuel_params);  $fuel_rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
} catch (Exception $e) {  die("Database Query Error: " . $e->getMessage());
}  // Calculate Merchandise KPIs
$kpi_merch = ['total' => 0, 'deliveries' => 0, 'releases' => 0, 'adjustments' => 0];
foreach ($merch_rows as $mr) {  $kpi_merch['total']++;  $mtype = strtolower($mr['movement_type']);  if ($mtype === 'delivery') {  $kpi_merch['deliveries'] += (float)$mr['quantity'];  } elseif ($mtype === 'sale' || $mtype === 'release') {  $kpi_merch['releases'] += abs((float)$mr['quantity']);  } elseif ($mtype === 'adjustment' || $mtype === 'stock correction' || $mtype === 'damaged item') {  $kpi_merch['adjustments']++;  }
}  // Calculate Fuel KPIs
$kpi_fuel = ['total' => 0, 'deliveries' => 0.0, 'dispensed' => 0.0, 'adjustments' => 0];
foreach ($fuel_rows as $fr) {  $kpi_fuel['total']++;  $mtype = strtolower($fr['movement_type']);  if ($mtype === 'delivery') {  $kpi_fuel['deliveries'] += (float)$fr['liters'];  } elseif ($mtype === 'dispensed') {  $kpi_fuel['dispensed'] += abs((float)$fr['liters']);  } elseif ($mtype === 'adjustment' || $mtype === 'stock correction' || $mtype === 'fuel variance') {  $kpi_fuel['adjustments']++;  }
}  // Fetch helper filter lists
$categories_list = [];
try {  $categories_stmt = $pdo->query("SELECT DISTINCT category FROM inventory_products WHERE category IS NOT NULL AND category != '' AND category != 'Fuel' ORDER BY category");  $categories_list = $categories_stmt->fetchAll(PDO::FETCH_COLUMN);
} catch (Exception $e) {}  $fuel_types_list = [];
try {  $fuel_types_stmt = $pdo->query("SELECT DISTINCT fuel_type FROM fuel_inventory ORDER BY fuel_type");  $fuel_types_list = $fuel_types_stmt->fetchAll(PDO::FETCH_COLUMN);
} catch (Exception $e) {}  $users_list = [];
try {  $users_stmt = $pdo->query("SELECT id, username, CONCAT(first_name, ' ', last_name) AS fullname FROM users ORDER BY username");  $users_list = $users_stmt->fetchAll(PDO::FETCH_ASSOC);
} catch (Exception $e) {}  include __DIR__ . '/../partials/header.php';
?>
