</div>  <script>
function viewMerchDetails(data) {  document.getElementById('mdMovementId').textContent = data.movement_id;  document.getElementById('mdRefNo').textContent = data.reference_no || '—';  document.getElementById('mdMoveType').textContent = data.movement_type;  document.getElementById('mdDateTime').textContent = data.date_time;  document.getElementById('mdPerformedBy').textContent = data.performed_by;  document.getElementById('mdSku').textContent = data.sku || '—';  document.getElementById('mdProdName').textContent = data.product_name;  document.getElementById('mdCategory').textContent = data.category || '—';  document.getElementById('mdUnit').textContent = data.unit || 'pcs';  document.getElementById('mdQuantity').textContent = (parseFloat(data.quantity) > 0 ? '+' : '') + parseFloat(data.quantity);  document.getElementById('mdPrevStock').textContent = parseFloat(data.prev_stock);  document.getElementById('mdNewStock').textContent = parseFloat(data.new_stock);  document.getElementById('mdRemarks').textContent = data.remarks || '—';  // Load loading text for dynamic fields  document.getElementById('mdInvValue').textContent = 'Loading...';  document.getElementById('mdStatus').textContent = 'Loading...';  document.getElementById('mdTotalDeliveries').textContent = 'Loading...';  document.getElementById('mdTotalReleased').textContent = 'Loading...';  document.getElementById('mdLastDeliveryDate').textContent = 'Loading...';  document.getElementById('mdLastMovement').textContent = 'Loading...';  // Show Modal  document.getElementById('merchDetailsModal').classList.add('show');  // Fetch dynamic product details  fetch('admin_inventory_history.php?action=get_product_details&product_id=' + data.product_id)  .then(response => response.json())  .then(res => {  if (res.success) {  const prod = res.product;  const totalStock = parseFloat(prod.current_stock);  const unitPrice = parseFloat(prod.unit_price) || 0;  const invVal = totalStock * unitPrice;  document.getElementById('mdInvValue').textContent = '₱' + invVal.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});  document.getElementById('mdStatus').textContent = prod.status.toUpperCase();  document.getElementById('mdTotalDeliveries').textContent = res.total_deliveries + ' ' + (prod.unit || 'pcs');  document.getElementById('mdTotalReleased').textContent = res.total_released + ' ' + (prod.unit || 'pcs');  document.getElementById('mdLastDeliveryDate').textContent = res.last_delivery_date;  document.getElementById('mdLastMovement').textContent = res.last_movement;  } else {  setMerchErrorDetails();  }  })  .catch(() => {  setMerchErrorDetails();  });
}  function setMerchErrorDetails() {  document.getElementById('mdInvValue').textContent = 'Error loading';  document.getElementById('mdStatus').textContent = 'Error';  document.getElementById('mdTotalDeliveries').textContent = '—';  document.getElementById('mdTotalReleased').textContent = '—';  document.getElementById('mdLastDeliveryDate').textContent = '—';  document.getElementById('mdLastMovement').textContent = '—';
}  function viewFuelDetails(data) {  document.getElementById('fdMovementId').textContent = data.movement_id;  document.getElementById('fdRefNo').textContent = data.reference_no || '—';  document.getElementById('fdMoveType').textContent = data.movement_type;  document.getElementById('fdDateTime').textContent = data.date_time;  document.getElementById('fdPerformedBy').textContent = data.performed_by;  document.getElementById('fdTank').textContent = data.tank;  document.getElementById('fdFuelType').textContent = data.fuel_type;  document.getElementById('fdLiters').textContent = (parseFloat(data.liters) > 0 ? '+' : '') + parseFloat(data.liters).toLocaleString() + ' L';  document.getElementById('fdPrevVol').textContent = parseFloat(data.prev_volume).toLocaleString() + ' L';  document.getElementById('fdNewVol').textContent = parseFloat(data.new_volume).toLocaleString() + ' L';  document.getElementById('fdRemarks').textContent = data.remarks || '—';  document.getElementById('fuelDetailsModal').classList.add('show');
}  function closeModal(id) {  document.getElementById(id).classList.remove('show');
}  // Modal self-closing on outside click
document.querySelectorAll('.modal-ov').forEach(modal => {  modal.addEventListener('click', function(e) {  if (e.target === this) {  this.classList.remove('show');  }  });
});  function exportData(type) {  const form = document.getElementById('filterForm');  const params = new URLSearchParams(new FormData(form)).toString();  window.location.href = 'admin_inventory_history.php?export=' + type + '&' + params;
}  function printInventoryHistory() {  const activeTab = '<?= $active_tab ?>';  const startDate = '<?= htmlspecialchars($start_date) ?>';  const endDate = '<?= htmlspecialchars($end_date) ?>';  const search = '<?= htmlspecialchars($search) ?>';  const category = '<?= htmlspecialchars($category) ?>';  const fuelType = '<?= htmlspecialchars($fuel_type) ?>';  const moveType = '<?= htmlspecialchars($move_type) ?>';  const perfBy = '<?= htmlspecialchars($perf_by) ?>';  // Build URL with all current filters  let url = 'admin_inventory_history.php?print=1&tab=' + activeTab;  url += '&start=' + encodeURIComponent(startDate);  url += '&end=' + encodeURIComponent(endDate);  if (search) url += '&search=' + encodeURIComponent(search);  if (category) url += '&category=' + encodeURIComponent(category);  if (fuelType) url += '&fuel_type=' + encodeURIComponent(fuelType);  if (moveType) url += '&move_type=' + encodeURIComponent(moveType);  if (perfBy) url += '&perf_by=' + encodeURIComponent(perfBy);  // Create or reuse hidden iframe for seamless printing  let iframe = document.getElementById('printFrame');  if (!iframe) {  iframe = document.createElement('iframe');  iframe.id = 'printFrame';  iframe.style.position = 'absolute';  iframe.style.width = '0';  iframe.style.height = '0';  iframe.style.border = 'none';  iframe.style.visibility = 'hidden';  document.body.appendChild(iframe);  }  // Load print content and trigger print dialog  iframe.onload = function() {  try {  iframe.contentWindow.focus();  iframe.contentWindow.print();  } catch (e) {  // Fallback to opening in new window if iframe printing fails  window.open(url, '_blank');  }  };  iframe.src = url;
}  function printReport() {  printInventoryHistory();
}
</script>  <?php include __DIR__ . '/../partials/footer.php'; ?>
